const row = $input.first().json;

function parseObject(value, label) {
  if (typeof value === 'string') {
    try {
      return JSON.parse(value);
    } catch {
      throw new Error(`${label} contains invalid JSON.`);
    }
  }

  return value ?? {};
}

function escapeHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#039;');
}

function displayText(value) {
  const cleaned = String(value ?? '').trim();

  return cleaned
    ? escapeHtml(cleaned).replaceAll('\n', '<br>')
    : '<span class="muted">Not provided</span>';
}

function renderList(values) {
  if (!Array.isArray(values) || values.length === 0) {
    return '<p class="muted">None listed.</p>';
  }

  return `
    <ul>
      ${values
        .map((value) => `<li>${displayText(value)}</li>`)
        .join('')}
    </ul>
  `;
}

const brief = parseObject(
  row.brief,
  'Campaign brief'
);

const content = parseObject(
  row.approved_content,
  'Approved campaign package'
);

const campaignBrief = brief.campaign ?? {};
const foundation = content.strategic_foundation ?? {};

const angles = Array.isArray(content.ad_angles)
  ? content.ad_angles
  : [];

const hooks = Array.isArray(content.hooks)
  ? content.hooks
  : [];

const ads = Array.isArray(content.ads)
  ? content.ads
  : [];

const images = Array.isArray(content.image_prompts)
  ? content.image_prompts
  : [];

const videos = Array.isArray(content.video_concepts)
  ? content.video_concepts
  : [];

const compliance = content.compliance_review ?? {};

const html = `
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">

  <meta
    name="viewport"
    content="width=device-width, initial-scale=1.0"
  >

  <title>
    ${escapeHtml(row.campaign_code)} Approved Campaign
  </title>

  <style>
    @page {
      size: A4;
      margin: 16mm 15mm;
    }
    @page:first {
      size: A4;
      margin: 0;
    }

    * {
      box-sizing: border-box;
    }

    html {
      print-color-adjust: exact;
      -webkit-print-color-adjust: exact;
    }

    body {
      margin: 0;
      color: #1f2937;
      font-family: Arial, Helvetica, sans-serif;
      font-size: 10.5pt;
      line-height: 1.55;
    }

    h1,
    h2,
    h3,
    p {
      margin-top: 0;
    }

    h1 {
      font-size: 30pt;
      line-height: 1.1;
    }

    h2 {
      margin: 0 0 14px;
      padding-bottom: 7px;
      border-bottom: 2px solid #d946ef;
      color: #111827;
      font-size: 19pt;
      break-after: avoid-page;
      page-break-after: avoid;
    }

    h3 {
      margin-bottom: 7px;
      color: #111827;
      font-size: 13pt;
    }

    ul,
    ol {
      padding-left: 22px;
    }

    li {
      margin-bottom: 6px;
    }

    .cover {
      min-height: 297mm;
      margin: 0;
      padding: 40mm 24mm 24mm;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      background:
        linear-gradient(
          135deg,
          #111827 0%,
          #312e81 55%,
          #86198f 100%
        );
      color: white;
      page-break-after: always;
    }

    .cover-label {
      margin-bottom: 18px;
      color: #f0abfc;
      font-size: 11pt;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    .cover h1 {
      max-width: 700px;
      margin-bottom: 18px;
      color: white;
    }

    .cover-summary {
      max-width: 650px;
      color: #e5e7eb;
      font-size: 13pt;
    }

    .cover-meta {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 12px;
    }

    .cover-meta-item {
      padding: 13px;
      background: rgba(255, 255, 255, 0.1);
      border: 1px solid rgba(255, 255, 255, 0.22);
      border-radius: 8px;
    }

    .cover-meta-label,
    .label {
      display: block;
      margin-bottom: 4px;
      color: #6b7280;
      font-size: 8pt;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .cover-meta-label {
      color: #d8b4fe;
    }

    .section {
      margin-bottom: 24px;
      break-inside: auto;
      page-break-inside: auto;
    }

    .section > h2 + * {
      break-before: avoid-page;
      page-break-before: avoid;
    }

    .page-break {
      break-before: auto;
      page-break-before: auto;
    }

    .grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 12px;
    }

    .card {
      padding: 15px;
      background: #f8fafc;
      border: 1px solid #e5e7eb;
      border-radius: 8px;
      break-inside: auto;
      page-break-inside: auto;
    }

    .card + .card {
      margin-top: 14px;
    }

    .card-accent {
      border-left: 4px solid #d946ef;
    }

    .summary-box {
      margin-bottom: 18px;
      padding: 18px;
      background: #faf5ff;
      border: 1px solid #e9d5ff;
      border-radius: 9px;
      font-size: 11pt;
    }

    .metadata-table {
      width: 100%;
      border-collapse: collapse;
      margin-bottom: 20px;
    }

    .metadata-table td {
      padding: 9px 11px;
      border: 1px solid #e5e7eb;
      vertical-align: top;
    }

    .metadata-table td:first-child {
      width: 30%;
      background: #f8fafc;
      color: #4b5563;
      font-weight: 700;
    }

    .identifier {
      display: inline-block;
      margin-bottom: 8px;
      padding: 3px 8px;
      background: #ede9fe;
      border-radius: 999px;
      color: #5b21b6;
      font-size: 8.5pt;
      font-weight: 700;
    }

    .copy-block {
      padding: 13px;
      background: white;
      border: 1px solid #e5e7eb;
      border-radius: 6px;
      white-space: normal;
    }

    .subsection {
      margin-top: 12px;
    }

    .muted {
      color: #6b7280;
    }

    .warning {
      padding: 14px;
      background: #fff7ed;
      border: 1px solid #fed7aa;
      border-left: 4px solid #f97316;
      border-radius: 7px;
      break-inside: auto;
      page-break-inside: auto;
    }

    .warning + .warning {
      margin-top: 14px;
    }

    .approval {
      padding: 18px;
      background: #ecfdf5;
      border: 1px solid #a7f3d0;
      border-radius: 9px;
      break-inside: avoid;
    }

    .approval-title {
      color: #047857;
      font-size: 14pt;
      font-weight: 700;
    }

    .footer-note {
      margin-top: 28px;
      padding-top: 10px;
      border-top: 1px solid #d1d5db;
      color: #6b7280;
      font-size: 8.5pt;
      text-align: center;
    }
  </style>
</head>

<body>
  <section class="cover">
    <div>
      <div class="cover-label">
        Approved Advertising Campaign
      </div>

      <h1>
        ${escapeHtml(row.company_name)}
      </h1>

      <p class="cover-summary">
        ${displayText(content.campaign_summary)}
      </p>
    </div>

    <div class="cover-meta">
      <div class="cover-meta-item">
        <span class="cover-meta-label">
          Campaign reference
        </span>

        ${escapeHtml(row.campaign_code)}
      </div>

      <div class="cover-meta-item">
        <span class="cover-meta-label">
          Approved version
        </span>

        ${escapeHtml(row.version_number)}
      </div>

      <div class="cover-meta-item">
        <span class="cover-meta-label">
          Client
        </span>

        ${escapeHtml(row.client_name)}
      </div>

      <div class="cover-meta-item">
        <span class="cover-meta-label">
          Reviewer
        </span>

        ${escapeHtml(row.reviewer_name)}
      </div>
    </div>
  </section>

  <section class="section">
    <h2>Campaign Overview</h2>

    <div class="summary-box">
      ${displayText(content.campaign_summary)}
    </div>

    <table class="metadata-table">
      <tr>
        <td>Company</td>
        <td>${displayText(row.company_name)}</td>
      </tr>

      <tr>
        <td>Website</td>
        <td>${displayText(row.website)}</td>
      </tr>

      <tr>
        <td>Campaign reference</td>
        <td>${displayText(row.campaign_code)}</td>
      </tr>

      <tr>
        <td>Approved version</td>
        <td>${displayText(row.version_number)}</td>
      </tr>

      <tr>
        <td>Campaign objective</td>
        <td>${displayText(row.objective)}</td>
      </tr>

      <tr>
        <td>Brand tone</td>
        <td>${displayText(row.brand_tone)}</td>
      </tr>

      <tr>
        <td>Offer</td>
        <td>${displayText(row.offer)}</td>
      </tr>

      <tr>
        <td>Call to action</td>
        <td>
          ${displayText(campaignBrief.call_to_action)}
        </td>
      </tr>
    </table>
  </section>

  <section class="section">
    <h2>Strategic Foundation</h2>

    <div class="grid">
      <article class="card card-accent">
        <span class="label">Audience summary</span>
        ${displayText(foundation.audience_summary)}
      </article>

      <article class="card card-accent">
        <span class="label">Primary problem</span>
        ${displayText(foundation.primary_problem)}
      </article>

      <article class="card card-accent">
        <span class="label">Desired outcome</span>
        ${displayText(foundation.desired_outcome)}
      </article>

      <article class="card card-accent">
        <span class="label">Offer positioning</span>
        ${displayText(foundation.offer_positioning)}
      </article>
    </div>
  </section>

  <section class="section">
    <h2>Advertising Angles</h2>

    ${angles.map((angle) => `
      <article class="card card-accent">
        <span class="identifier">
          ${escapeHtml(angle.angle_id)}
        </span>

        <h3>${escapeHtml(angle.name)}</h3>

        <div class="subsection">
          <span class="label">Awareness stage</span>
          ${displayText(angle.awareness_stage)}
        </div>

        <div class="subsection">
          <span class="label">Core message</span>
          ${displayText(angle.core_message)}
        </div>

        <div class="subsection">
          <span class="label">Rationale</span>
          ${displayText(angle.rationale)}
        </div>
      </article>

    `).join('')}
  </section>

  <section class="section">
    <h2>Advertising Hooks</h2>

    <ol>
      ${hooks.map((hook) => `
        <li>
          <strong>${escapeHtml(hook.hook_id)}</strong>
          -
          ${displayText(hook.hook_text)}
          <span class="muted">
            (${escapeHtml(hook.angle_id)})
          </span>
        </li>
      `).join('')}
    </ol>
  </section>

  <section class="section">
    <h2>Approved Ad Copy</h2>

    ${ads.map((ad) => `
      <article class="card">
        <span class="identifier">
          ${escapeHtml(ad.ad_id)}
          ·
          ${escapeHtml(ad.angle_id)}
        </span>

        <h3>${escapeHtml(ad.headline)}</h3>

        <div class="subsection">
          <span class="label">Primary text</span>

          <div class="copy-block">
            ${displayText(ad.primary_text)}
          </div>
        </div>

        <div class="subsection">
          <span class="label">Description</span>
          ${displayText(ad.description)}
        </div>

        <div class="subsection">
          <span class="label">Call to action</span>
          ${displayText(ad.call_to_action)}
        </div>
      </article>

    `).join('')}
  </section>

  <section class="section">
    <h2>Image Creative Directions</h2>

    ${images.map((image) => `
      <article class="card">
        <span class="identifier">
          ${escapeHtml(image.prompt_id)}
          ·
          ${escapeHtml(image.angle_id)}
        </span>

        <h3>${escapeHtml(image.concept_name)}</h3>

        <div class="subsection">
          <span class="label">AI image prompt</span>

          <div class="copy-block">
            ${displayText(image.prompt)}
          </div>
        </div>

        <div class="subsection">
          <span class="label">Suggested overlay</span>
          ${displayText(image.overlay_text)}
        </div>
      </article>

    `).join('')}
  </section>

  <section class="section">
    <h2>Video Creative Directions</h2>

    ${videos.map((video) => `
      <article class="card">
        <span class="identifier">
          ${escapeHtml(video.concept_id)}
          ·
          ${escapeHtml(video.duration_seconds)} seconds
        </span>

        <h3>${escapeHtml(video.concept_name)}</h3>

        <div class="subsection">
          <span class="label">Opening hook</span>
          ${displayText(video.opening_hook)}
        </div>

        <div class="subsection">
          <span class="label">Scene plan</span>
          ${renderList(video.scene_plan)}
        </div>

        <div class="subsection">
          <span class="label">Voiceover</span>

          <div class="copy-block">
            ${displayText(video.voiceover)}
          </div>
        </div>

        <div class="subsection">
          <span class="label">End card</span>
          ${displayText(video.end_card_text)}
        </div>
      </article>

    `).join('')}
  </section>

  <section class="section">
    <h2>Compliance and Quality Review</h2>

    <div class="warning">
      <h3>Unsupported claims to avoid</h3>
      ${renderList(compliance.unsupported_claims)}
    </div>



    <div class="warning">
      <h3>Policy or sensitivity risks</h3>
      ${renderList(compliance.sensitive_or_policy_risks)}
    </div>



    <div class="warning">
      <h3>Items requiring human confirmation</h3>
      ${renderList(compliance.notes_for_human_reviewer)}
    </div>
  </section>

  <section class="section">
    <h2>Approval Record</h2>

    <div class="approval">
      <div class="approval-title">
        Approved for production
      </div>

      <p>
        <strong>Reviewer:</strong>
        ${displayText(row.reviewer_name)}
      </p>

      <p>
        <strong>Reviewer email:</strong>
        ${displayText(row.reviewer_email)}
      </p>

      <p>
        <strong>Approval feedback:</strong><br>
        ${displayText(
          row.approval_feedback ||
          'No additional approval feedback.'
        )}
      </p>
    </div>

    <div class="footer-note">
      Generated automatically by AdFlow AI.
      Human approval is required before production or publication.
    </div>
  </section>
</body>
</html>
`;

return [
  {
    json: {
      ...row,

      folder_name:
        `${row.campaign_code} - ${row.company_name}`,

      html_file_name:
        'index.html',

      pdf_file_name:
        `${row.campaign_code}-approved-campaign.pdf`,

      pdf_html: html,
    },
  },
];
